mutation:
mutation RegisterFrenchSelfDesignPage($resourceId: ID!, $translations: [TranslationInput!]!) {
  translationsRegister(resourceId: $resourceId, translations: $translations) {
    translations {
      key
      locale
      value
      outdated
      updatedAt
    }
    userErrors {
      field
      message
    }
  }
}

readbackQuery:
query ReadBackFrenchSelfDesignPage($id: ID!, $locale: String!) {
  node(id: $id) {
    ... on Page {
      id
      title
      handle
      templateSuffix
      isPublished
      updatedAt
    }
  }
  translatableResource(resourceId: $id) {
    resourceId
    translatableContent {
      key
      value
      digest
      locale
    }
    translations(locale: $locale) {
      key
      value
      locale
      outdated
      updatedAt
    }
  }
}
